function census(text){
 const labels=[],types=[],keySets=[],fieldShapes=[],orderedTypes=[];
 const sl=new Set(),st=new Set(),sk=new Set(),sf=new Set();
 let dataEventCount=0,doneMarkerCount=0,parseErrorCount=0;
 const selected=['response','item','delta','content','output','choices','message'];
 for(const rawLine of String(text??'').split(/\r?\n/)){
