 if(lines.some(x=>x.startsWith('data:')||x.startsWith('event:')))return {...out,framing:'SSE_DATA_LINES'};
 if(lines.length>1){
  let n=0;
  for(const line of lines){try{const p=JSON.parse(line);if(p&&typeof p==='object')n+=1;}catch{}}
  if(n===lines.length)return {...out,framing:'NDJSON'};
 }
 return out;
}
